+
+    public CacheService(
+            @Qualifier("deviceCaffeine") Cache<String, Object> deviceCache,
+            @Qualifier("subscribeCaffeine") Cache<String, Object> subscribeCache,
+            @Qualifier("transactionCaffeine") Cache<String, Object> transactionCache,
