+        try {
+            transactionCache.put(transactionId, transaction);
+            log.debug("Transaction cached: {}", transactionId);
+        } catch (Exception e) {
+            log.warn("Failed to cache transaction: {}", transactionId, e);
+        }
+    }
+
+    /**
+     * 移除事务信息
