+/**
+ * Inlined version of the 'bytes' package
+ * Original: https://github.com/visionmedia/bytes.js
+ * License: MIT
+ *
+ * Copyright(c) 2012-2014 TJ Holowaychuk
+ * Copyright(c) 2015 Jed Watson
