+func scanStmtVars(s *parser.Statement, vars map[string]struct{}) {
+	if s == nil {
+		return
+	}
+	switch {
+	case s.Let != nil:
+		exprVars(s.Let.Value, vars)
+	case s.Var != nil:
+		exprVars(s.Var.Value, vars)
+	case s.Assign != nil:
+		exprVars(s.Assign.Value, vars)
+	case s.Return != nil:
+		exprVars(s.Return.Value, vars)
+	case s.Expr != nil:
