+		if p.Call != nil {
+			if _, ok := aggNeedsItems[p.Call.Func]; ok {
+				found = true
+				return
+			}
+			for _, a := range p.Call.Args {
+				scanExpr(a)
+			}
+		}
+		if p.Struct != nil {
+			for _, f := range p.Struct.Fields {
+				scanExpr(f.Value)
+			}
+		}
+		if p.List != nil {
+			for _, el := range p.List.Elems {
+				scanExpr(el)
+			}
+		}
+		if p.Map != nil {
+			for _, it := range p.Map.Items {
+				scanExpr(it.Key)
+				scanExpr(it.Value)
+			}
+		}
+		if p.Group != nil {
+			scanExpr(p.Group)
+		}
+		if p.If != nil {
+			scanExpr(p.If.Cond)
+			scanExpr(p.If.Then)
+			scanExpr(p.If.Else)
+			if p.If.ElseIf != nil {
+				scanExpr(p.If.ElseIf.Cond)
+				scanExpr(p.If.ElseIf.Then)
+				scanExpr(p.If.ElseIf.Else)
